package com.chatsystem.admin.ui.cell;

import com.chatsystem.shared.model.*; import com.chatsystem.shared.service.AdminService; import javafx.scene.control.*; import javafx.scene.layout.*; import java.util.function.LongConsumer;
public final class ModerationCaseCell extends ListCell<SpamReport>{private final AdminService service;private final LongConsumer open;public ModerationCaseCell(AdminService service,LongConsumer open){this.service=service;this.open=open;}@Override protected void updateItem(SpamReport report,boolean empty){super.updateItem(report,empty);if(empty||report==null){setGraphic(null);return;}Label text=new Label();text.textProperty().bind(javafx.beans.binding.Bindings.createStringBinding(()->"WR-"+report.getId()+"   "+report.getReason()+"   "+service.getUser(report.getReportedUserId()).map(UserAccount::getDisplayName).orElse("Unavailable")+"   "+report.getCreatedAt()+"   "+report.getStatus(),report.statusProperty()));Button inspect=new Button("Inspect");inspect.getStyleClass().add("small-button");inspect.setOnAction(e->open.accept(report.getId()));HBox row=new HBox(16,text,inspect);HBox.setHgrow(text,Priority.ALWAYS);row.getStyleClass().add("list-row");setGraphic(row);}}
